package com.projecteden.achievement.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.achievement.dto.AchievementResponse;import com.projecteden.achievement.service.AchievementService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/achievements")public class AchievementController{private final AchievementService service;public AchievementController(AchievementService service){this.service=service;}@GetMapping("/me")public List<AchievementResponse> get(@AuthenticationPrincipal User user){return service.getMyAchievements(user.getId());}}
